import http from "node:http";
import type { AddressInfo } from "node:net";
const CLIENT = process.env.CLIENT_TS!;
const { LocalLlmClient } = await import(CLIENT);

const tool = { type: "function", function: { name: "read_file", description: "r", parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] } } };
type Ident = "llamacpp" | "ollama" | "vllm" | "gateway";
let ident: Ident = "llamacpp";
let mode = "ok"; // ok|503|badjson|drop|404|missing|generic|noversion|noprops
let seen: string[] = [];
let lastChat: any = {}; let lastHeaders: any = {};
const server = http.createServer((req, res) => {
  let body = ""; req.on("data", c => body += c);
  req.on("end", () => {
    seen.push(`${req.method} ${req.url}`);
    res.setHeader("Content-Type", "application/json");
    if (req.url === "/v1/models") {
      if (mode === "503") { res.statusCode = 503; return res.end("x"); }
      if (mode === "badjson") return res.end("{not json");
      if (mode === "drop") return req.socket.destroy();
      if (mode === "404") { res.statusCode = 404; return res.end("nf"); }
      if (mode === "missing") return res.end(JSON.stringify({ data: [{ id: "other" }] }));
      if (mode === "generic") return res.end(JSON.stringify({ data: [{ id: "m" }] }));
      const e: any = { id: "m" };
      if (ident === "llamacpp") { e.owned_by = "llamacpp"; e.meta = { n_ctx_train: 32768 }; }
      if (ident === "ollama") { e.owned_by = "ollama"; }
      if (ident === "vllm") { e.owned_by = "vllm"; e.max_model_len = 8192; }
      if (ident === "gateway") { e.owned_by = "gateway"; e.limits_version = "1"; e.context_length = 32768; }
      return res.end(JSON.stringify({ data: [e] }));
    }
    if (req.url === "/props") { if (mode === "noprops") { res.statusCode = 503; return res.end("x"); } return res.end(JSON.stringify({ default_generation_settings: { n_ctx: 16384 } })); }
    if (req.url === "/api/version") return res.end(JSON.stringify({ version: "0.5.0" }));
    if (req.url === "/api/show") return res.end(JSON.stringify({ model: "m", model_info: { "llama.context_length": 8192 } }));
    if (req.url === "/version") { if (mode === "noversion") { res.statusCode = 503; return res.end("x"); } return res.end(JSON.stringify({ version: "0.10.0" })); }
    if (req.url === "/v1/tokenize") { res.statusCode = 404; return res.end("nf"); }
    if (req.url === "/tokenize") return res.end(JSON.stringify({ count: 7, tokens: [1], max_model_len: 8192 }));
    if (req.url === "/v1/chat/completions") { lastChat = JSON.parse(body); lastHeaders = req.headers; return res.end(JSON.stringify({ choices: [{ message: { role: "assistant", content: "ok" }, finish_reason: "stop" }], usage: {} })); }
    res.statusCode = 404; res.end("nf");
  });
});
await new Promise<void>(r => server.listen(0, "127.0.0.1", r));
const ep = `http://127.0.0.1:${(server.address() as AddressInfo).port}/v1`;

async function observe(c: any) {
  seen = [];
  lastChat = {}; lastHeaders = {};
  await c.chatCompletion([{ role: "user", content: "hi" }], [tool]);
  let tok = "-";
  try { seen = []; await c.countRequestTokens([{ role: "user", content: "hi" }], [], "r1"); tok = seen.filter(s => s.includes("tokenize")).join("|"); } catch (e: any) { tok = "ERR:" + (e.code ?? e.message).toString().slice(0, 20) ; }
  return `strict=${lastChat.tools?.[0]?.function?.strict ?? "-"} hdr=${lastHeaders["x-task-class"] ?? "-"} tok=${tok}`;
}
let n = 0;
async function scenario(init: Ident, rediscover: string, label?: string) {
  // fresh endpoint key per scenario: vary path suffix is not possible on mock; use different hostname alias
  const alias = ep.replace("127.0.0.1", `127.${(++n >> 8) & 255}.${n & 255}.1`);
  ident = init; mode = "ok";
  const c = new LocalLlmClient({ endpoint: alias, model: "m", apiKey: "k", taskClass: "subagent" } as any);
  const a = await c.discoverAdvertisement();
  const k0 = c.getDetectedServerKind();
  mode = rediscover;
  const b = await c.discoverAdvertisement();
  const k1 = c.getDetectedServerKind();
  const obs = await observe(c);
  console.log(`${init.padEnd(9)} -> ${rediscover.padEnd(9)} initial=${k0}/${a.state} after=${k1}/${b.state} ${obs}`);
}
for (const init of ["llamacpp", "ollama", "vllm", "gateway"] as Ident[])
  for (const m of ["503", "badjson", "drop", "404", "missing", "generic", "noversion", "noprops"])
    await scenario(init, m);
// Replacement: vllm then swapped to llamacpp that lists a different model (missing) -> retained?
{
  const alias = ep.replace("127.0.0.1", `127.9.9.1`);
  ident = "vllm"; mode = "ok";
  const c = new LocalLlmClient({ endpoint: alias, model: "m", apiKey: "k", taskClass: "subagent" } as any);
  await c.discoverAdvertisement(); console.log("REPLACE vllm initial", c.getDetectedServerKind());
  ident = "llamacpp"; mode = "missing"; await c.discoverAdvertisement();
  console.log("REPLACE vllm->llamacpp(model not listed)", c.getDetectedServerKind(), await observe(c));
  mode = "503"; for (let i = 0; i < 3; i++) await c.discoverAdvertisement();
  console.log("REPLACE after 3x 503", c.getDetectedServerKind());
  // another client on same endpoint (new session / provider switch)
  const c2 = new LocalLlmClient({ endpoint: alias, model: "m2", apiKey: "other-account", taskClass: "subagent" } as any);
  console.log("NEW CLIENT same endpoint kind before any discovery:", c2.getDetectedServerKind());
}
{
  const alias = ep.replace("127.0.0.1", `127.9.9.2`);
  ident = "gateway"; mode = "ok";
  const c = new LocalLlmClient({ endpoint: alias, model: "m", apiKey: "k", taskClass: "subagent" } as any);
  await c.discoverAdvertisement();
  ident = "llamacpp"; mode = "404"; await c.discoverAdvertisement();
  console.log("REPLACE gateway->standalone(404 /models)", c.getDetectedServerKind(), await observe(c));
}
